#!/usr/bin/env bash
# GENERATED by hand once, from gpu7_watson12.series - the 12 watson pass-3 series this
# replication covers (every 3rd line of probes/trux/pass3_watson.txt).
#
# The list is inline on purpose. trux_dispatch copies ONE file to gpu7, so neither an
# exported env var (job_006: FATAL SERIES_LIST required) nor a sibling file in the bridge
# inbox (job_007: cat: .../inbox/gpu7_watson12.series: No such file) reaches the job. A
# generated job file that carries its own arguments is the only shape that survives the
# transport. Edit gpu7_watson12.series and regenerate this file, do not hand-edit names.
SERIES_LIST="std_equity_1d_10104 std_equity_1d_14008 std_equity_1d_20482 std_equity_1d_47896 std_equity_1d_66157 std_equity_1d_89525 std_fi_1d_uk_5y std_fi_1d_us_2y std_fi_1d_jp_7y std_fx_1d_eurusd std_fx_1d_usdmxn std_fx_1h_usdchf"
export SERIES_LIST
exec bash "$(dirname "$0")/gpu7_030_replicate.sh"
